        for cell in row:
            counter[cell] += 1

    bg = max(counter, key=counter.get)
    result = deepcopy(grid)

    for row in result:
        # Uniform rows stay as-is
        if len(set(row)) <= 1:
            continue

        non_bg = set(cell for cell in row if cell != bg)
        if len(non_bg) != 1:
            continue

        other = list(non_bg)[0]

        # Get all positions of other color
        positions = [i for i, c in enumerate(row) if c == other]

        is_single_block = len(positions) > 0 and all(positions[i+1] == positions[i] + 1 for i in range(len(positions)-1))

        if not is_single_block:
            continue

        # Must have bg before AND after the single other-block
        has_bg_before = False
        has_bg_after = False

        for i in range(len(positions)):
            if i == 0:
                has_bg_before = (positions[0] > 0 and row[positions[0]-1] == bg)
            if i == len(positions) - 1:
                has_bg_after = (positions[-1] < len(row) - 1 and row[positions[-1]+1] == bg)

        if has_bg_before and has_bg_after:
            # Replace all bg with 1
            for i in range(len(row)):
                if row[i] == bg:
                    row[i] = 1

    return result
